import {homeDemoMarkup} from './home-demo.mjs';
import {createExerciseRotation} from './exercise-rotation.mjs';
import {LANGUAGES,LAYOUTS,DEFAULT_SETTINGS} from './data.mjs';
import {createProgress} from './core.mjs';
import {learningFor,progressFor,recommendations,targetWords,contentText,contentPool,controlText,validateText,controlSummary,backupData,parseBackup,METRICS_VERSION} from './learning.mjs';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const names={letters:'Связный текст',shift:'Заглавные и Shift',numbers:'Цифры и знаки',work:'Рабочее сообщение'};
const button=(action,text,klass='outline-button')=>`<button class="${klass}" data-coach="${action}">${text}</button>`;
const round=x=>Number.isFinite(x)?Math.round(x):'—';
export function createCoach(api){
 const rotation=createExerciseRotation({storage:localStorage});
 let draft='',titleDraft='',pendingImport=null;
 const state=()=>{let data=api.getData(),settings=data.settings,lang=settings.language,layout=settings.layouts[lang];return{data,settings,lang,layout,model:learningFor(data,lang,layout),progress:progressFor(data,lang,layout)}};
 function homeMarkup(){const s=state();return `<section class="dev-home" aria-label="Практика скорости печати"><div class="home-hero"><span class="eyebrow">// TYPE FASTER. BUILD MORE.</span><h2>Печатай быстрее.<br><span>Думай о коде.</span></h2><p>Тренируй скорость программиста: уверенные буквы, ровный ритм текста и точные символы кода.</p>${homeDemoMarkup()}</div><div class="home-modes"><button class="home-mode" data-view="practice"><span class="mode-mark">Aa</span><span class="eyebrow">01 · БУКВЫ</span><h3>Разгони пальцы</h3><p>Короткие задания на буквы.<br>Укрепляй точность и скорость.</p><b>Практиковаться →</b></button><button class="home-mode" data-view="library"><span class="mode-mark">txt</span><span class="eyebrow">02 · ТЕКСТ</span><h3>Найди свой ритм</h3><p>Связные тексты, цифры, знаки.<br>Можно вставить свой материал.</p><b>Выбрать текст →</b></button><button class="home-mode code-mode" data-view="code"><span class="mode-mark">{ }</span><span class="eyebrow">03 · КОД</span><h3>Ускорь набор кода</h3><p>JavaScript, TypeScript, Python, C и C++.<br>Настоящие строки и конструкции.</p><b>Печатать код →</b></button></div><div class="home-bottom"><div><h3>Не знаешь, куда поставить пальцы?</h3><p>Короткие уроки помогут освоить клавиши по шагам.</p></div><button class="outline-button" data-view="lessons">Открыть уроки →</button><button class="soft-button" data-view="test">Проверить скорость →</button></div><div class="home-footnote"><span>${LANGUAGES[s.lang].code} · ${esc(LAYOUTS[s.layout].name)} · прогресс сохраняется</span><span>Выбери практику → набери текст → сравни результат</span></div></section>`;}
 function libraryMarkup(){let s=state();return`<div class="coach-intro compact"><div><span class="eyebrow">ПЕРЕНОС В РАБОТУ</span><h2>Твой текст. Твоя практика.</h2><p>Готовые фрагменты или собственный текст. Обработка остаётся в браузере.</p></div></div><div class="text-categories">${Object.entries(names).map(([id,name])=>`<button class="text-category" data-coach-run="${id}"><span>${id==='shift'?'Aa':id==='numbers'?'12:30':id==='work'?'→':'аб'}</span><h3>${name}</h3><p>${id==='numbers'?'Даты, время, суммы и номера':id==='shift'?'Регистр и координация рук':id==='work'?'Письма и обычные сообщения':'Осмысленные предложения'}</p></button>`).join('')}</div><section class="custom-text-card"><h3>Мой текст</h3><label for="libraryDraft">Вставь заметку, документацию или фрагмент кода</label><textarea id="libraryDraft" rows="6" maxlength="5000" placeholder="Текст остаётся на этом устройстве. Переносы строк будут заменены пробелами.">${esc(draft)}</textarea><div class="custom-text-options"><label for="libraryTitle">Название<input id="libraryTitle" maxlength="80" value="${esc(titleDraft)}" placeholder="Например, README или code review"></label><label class="checkbox-label"><input type="checkbox" id="keepCustom">Сохранить в моей библиотеке</label></div><p class="storage-note">До 5000 символов. Копирование идёт по словам; пробелы и переносы нормализуются. Русские буквы ё и е остаются разными.</p><p class="validation-error" id="libraryError" role="alert"></p>${button('custom-start','Тренироваться с моим текстом →','primary-button')}</section>${s.data.library.length?`<section class="library-saved"><h3>На этом устройстве</h3>${s.data.library.map(t=>`<div class="library-item"><div><b>${esc(t.title)}</b><small>${t.text.length} символов · ${LANGUAGES[t.lang]?.name||t.lang}</small></div><button class="outline-button" data-coach-text="${esc(t.id)}">Начать</button><button class="icon-button" data-coach-remove="${esc(t.id)}" aria-label="Убрать ${esc(t.title)}">×</button></div>`).join('')}</section>`:''}<p class="storage-note">Подсказки клавиатуры соответствуют выбранной раскладке. Для символов вне этой схемы воспользуйся своей клавиатурой.</p>`}
 function skillsMarkup(){let s=state(),recs=recommendations(s.model,s.lang),check=controlSummary(s.model),keys=[...LANGUAGES[s.lang].alphabet+'0123456789'];return`<section class="stat-section coach-skills"><h3>Что стоит потренировать</h3>${recs.length?`<div class="recommendations">${recs.map(t=>`<article><b>${esc(t.key.toUpperCase())}</b><p>${t.reason}</p><button class="soft-button" data-coach-target="${esc(t.type+':'+t.key)}">Короткая практика →</button></article>`).join('')}</div>`:'<p class="storage-note">Пока мало повторных наблюдений. Для вывода о букве нужны хотя бы 8 вводов, о переходе — 5. Они собираются во всех новых занятиях.</p>'}<div class="skill-map" aria-label="Наблюдения по клавишам">${keys.map(c=>{let k=s.model.keys[c],n=k?.observations||0,accuracy=n?(1-k.errors/n)*100:null;return`<span class="skill-cell ${n<8?'unknown':accuracy>=97?'reliable':'attention'}" title="${esc(c.toUpperCase())}: ${n} вводов${n?', '+round(accuracy)+'% точности':''}${n<8?' · мало данных':''}">${esc(c.toUpperCase())}<small>${n<8?'·':round(accuracy)+'%'}</small></span>`}).join('')}</div><p class="storage-note">Точки — мало данных. Моторные интервалы исключают исправления и паузы длиннее 2 секунд; время всего занятия сохраняется.</p></section><section class="stat-section"><h3>Контроль на новых текстах</h3>${check.count?`<div class="control-mini"><span>Первый: <b>${round(check.baseline.cpm)} CPM</b></span><span>Последний: <b>${round(check.latest.cpm)} CPM</b></span><span>Точность последнего: <b>${round(check.latest.accuracy)}%</b></span>${check.range?`<span>Последние 3: <b>${round(check.range[0])}–${round(check.range[1])} CPM</b></span>`:''}</div><p class="storage-note">Разные новые тексты одного корпуса. Разница отдельных попыток ещё не доказывает изменение навыка.</p>`:'<p class="storage-note">Здесь появятся завершённые попытки на контрольных текстах без пауз и запросов помощи.</p>'}${button('control','Пройти независимую проверку')}</section>`}
 function dataMarkup(){return`<section class="setting-section"><h3>Мои данные</h3><p class="storage-note">Прогресс, настройки и сохранённые тексты находятся в этом браузере. Резервная копия позволяет перенести их на другое устройство.</p><div class="coach-actions data-actions">${button('export','Скачать резервную копию')}<label class="outline-button file-button" tabindex="0" role="button">Загрузить копию<input id="backupFile" type="file" accept="application/json,.json"></label>${button('reset','Очистить данные','danger-button')}${localStorage.getItem('ten-fingers-undo')?button('undo','Восстановить предыдущие данные'):''}</div>${api.getData().trash?.length?button('restore-texts','Вернуть убранные тексты','soft-button'):''}${button('metrics','Как считаются показатели','soft-button')}</section>`}
 function start(words,ctx){api.startActivity(words,ctx)}
 function runType(type){let s=state(),index=rotation.pick('text-v2-'+s.lang+'-'+s.layout+'-'+type,contentPool(s.lang,type).length),text=contentText(s.lang,type,index);let result=validateText(text,s.layout);start(result.words,{activity:type,title:names[type],reason:type==='numbers'?'Практика цифрового ряда и знаков. Внимательно прочитай фрагмент перед началом.':'Новый контекст для привычных клавиш.',contentId:'text-v2-'+s.lang+'-'+type+'-'+index})}
 function startControl(){let s=state(),c=controlText(s.model,s.lang);if(!c){api.openDialog('Все новые проверки пройдены','<p class="help-copy">В текущем корпусе больше нет незнакомых контрольных текстов. Можно продолжать обычную практику; повтор знакомого текста не будет отмечен как независимая проверка.</p>');return}start(c.text.split(' '),{activity:'control',title:'Независимая проверка',reason:'Этот текст не встречался в обучении. Помощь скрыта; F1 покажет её по запросу. Попытки с паузой или помощью сохранятся, но не войдут в сравнение.',hideHints:true,strictTest:true,contentId:c.id})}
 function resultExtra(result){return `<div class="result-coach"><p>${result.accuracy<95?'Уменьши темп и постарайся набрать точнее.':'Продолжай в ровном темпе и постепенно ускоряйся.'}</p><button class="soft-button" data-view="library">Выбрать другой текст →</button></div>`;}
 function metricsDialog(){api.openDialog('Показатели без скрытых штрафов',`<div class="help-copy"><p><b>CPM</b> — правильные символы конечного текста за активную минуту. Включены пробелы между введёнными словами, знаки и цифры. Финальный пробел не учитывается. <b>WPM = CPM ÷ 5.</b></p><p><b>Точность ввода</b> — доля правильных вставленных символов среди всех вставок. Удалённая опечатка остаётся в этом числе. Повторная ошибка считается новой попыткой. Управляющие клавиши и пробел перехода не входят в точность букв.</p><p><b>С первого раза</b> — доля позиций, куда первый символ попал верно. <b>Точность финала</b> учитывает выравнивание с эталоном: одна вставка не превращает всё слово в цепочку ошибок.</p><p><b>Исправления</b> — операции удаления или замены. Время исправлений измеряется от начала удаления до следующего правильного ввода, когда эту связь можно установить.</p><p>Практика разрешает паузу. Тесты и контроль с паузой сохраняются как учебные попытки и исключаются из рекордов и независимого сравнения. Таймер начинается с первого принятого символа.</p><p>Новая версия метрик: ${METRICS_VERSION}. Старые результаты сохраняются со своими исходными числами; сравнение роста строится по новым контрольным попыткам.</p></div>`)}
 function rememberUndo(){localStorage.setItem('ten-fingers-undo',JSON.stringify(api.getData()))}
 function downloadBackup(){let blob=new Blob([backupData(api.getData())],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ten-fingers-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function handleClick(b){let action=b.dataset.coach,s=state();if(b.dataset.coachRun){runType(b.dataset.coachRun);return true}if(b.dataset.coachTarget){let [type,key]=b.dataset.coachTarget.split(':'),target=recommendations(s.model,s.lang).find(t=>t.type===type&&t.key===key);if(target)start(targetWords(s.lang,target),{activity:'target',title:`Практика «${key}»`,reason:target.reason,target:type+':'+key});return true}if(b.dataset.coachText){let text=s.data.library.find(t=>t.id===b.dataset.coachText);if(text){start(validateText(text.text,s.layout).words,{activity:'custom',title:text.title,reason:'Твой материал. При необходимости переключай язык ввода.',contentId:text.id})}return true}if(b.dataset.coachRemove){s.data.trash??=[];let index=s.data.library.findIndex(t=>t.id===b.dataset.coachRemove);if(index>=0)s.data.trash.push(s.data.library.splice(index,1)[0]);api.persist();api.render();api.toast('Текст убран. Его можно вернуть из настроек данных.');return true}if(!action)return false;
  switch(action){case'control':startControl();break;
   case'custom-start':{draft=document.getElementById('libraryDraft').value;titleDraft=document.getElementById('libraryTitle').value.trim();let result=validateText(draft,s.layout),error=document.getElementById('libraryError');if(result.text.length<3){error.textContent='Добавь хотя бы несколько символов.';break}if(result.words.some(w=>w.length>80)){error.textContent='Слово длиннее 80 символов. Раздели длинную ссылку или строку пробелами.';break}if(/[\u200b-\u200f\u202a-\u202e\u2060\u2066-\u2069]/u.test(result.text)){error.textContent='В тексте есть невидимые символы. Убери скрытые разделители и знаки направления текста, затем повтори.';break}if(result.unsupported.some(c=>/[^\x20-\x7e\u0400-\u04ff\u00c0-\u024f]/u.test(c))){error.textContent='В этом режиме поддерживаются буквы, цифры и обычные знаки. Убери эмодзи и сложные составные символы.';break}let id='local-'+Date.now();if(document.getElementById('keepCustom').checked){s.data.library.push({id,title:titleDraft||'Мой текст',text:result.text,lang:s.lang,at:Date.now()});api.persist()}start(result.words,{activity:'custom',title:titleDraft||'Мой текст',reason:'Текст обработан локально. Повторы пробелов и переносы строк заменены одним пробелом.',contentId:id});break}
   case'restore-texts':s.data.library.push(...(s.data.trash||[]));s.data.trash=[];api.persist();api.render();break;case'export':downloadBackup();break;case'metrics':metricsDialog();break;
   case'import-confirm':if(pendingImport){rememberUndo();api.replaceData(pendingImport);pendingImport=null;document.getElementById('dialog').close();api.navigate('home');api.toast('Копия восстановлена. Предыдущие данные можно вернуть в настройках.')}break;
   case'reset':api.openDialog('Очистить данные этого браузера?',`<div class="help-copy"><p>Будут сброшены прогресс, настройки и библиотека. Предыдущая версия останется доступна через кнопку восстановления в этом браузере.</p></div><div class="coach-actions">${button('export','Сначала скачать копию')}${button('reset-confirm','Сбросить с возможностью восстановления','danger-button')}</div>`);break;
   case'reset-confirm':rememberUndo();api.replaceData({version:2,settings:structuredClone(DEFAULT_SETTINGS),progress:Object.fromEntries(Object.keys(LANGUAGES).map(l=>[l,createProgress()])),legacyLessons:{},guideSeen:false});document.getElementById('dialog').close();api.navigate('home');break;
   case'undo':{let raw=localStorage.getItem('ten-fingers-undo');if(raw){let previous;try{previous=parseBackup(backupData(JSON.parse(raw)));}catch{api.toast('Предыдущая копия повреждена. Используй проверенную резервную копию.');break;}rememberUndo();api.replaceData(previous);api.navigate('home');api.toast('Предыдущие данные восстановлены.')}break}
  }return true;
 }
 async function handleChange(el){if(el.id!=='backupFile')return false;try{let file=el.files?.[0];if(!file)return true;if(file.size>15000000)throw new Error('Файл слишком большой.');pendingImport=parseBackup(await file.text());let count=Object.values(pendingImport.learning||{}).reduce((sum,m)=>sum+m.activities.length,0);api.openDialog('Восстановить резервную копию?',`<div class="help-copy"><p>В копии ${count} новых занятий и ${pendingImport.library?.length||0} сохранённых текстов. Текущие данные будут заменены; их можно вернуть через восстановление в настройках.</p></div>${button('import-confirm','Восстановить копию','primary-button')}`)}catch(e){api.toast(e.message);el.value=''}return true}
 function rememberDraft(el){if(el.id==='libraryDraft')draft=el.value;if(el.id==='libraryTitle')titleDraft=el.value}
 return{newText(type){if(!names[type])return false;runType(type);return true;},homeMarkup,libraryMarkup,skillsMarkup,dataMarkup,resultExtra,handleClick,handleChange,rememberDraft,metricsDialog};
}
